                scenario = "Harbor Pets stores bookings and each clinic's slot counter in one container partitioned by /clinicId.",
                whyWrong = mapOf(
                    0 to "An ETag condition protects one write from a lost update. If the second call fails, the first has already been saved, leaving the data half-updated.",
