            B.q("ai-m3-18", "ai-cosmos-perf", "Readers in other regions may lag the write region, but never by more than 5 minutes or 100 versions, and the app wants ordered reads. Which consistency level states exactly this?", listOf("Bounded staleness", "Session", "Consistent prefix", "Eventual"), setOf(0), "Bounded staleness guarantees that reads lag writes by at most K versions or T time, and it keeps order. That is the only level where you configure a maximum lag.",
                scenario = "Marlow Books shows stock levels from a multi-region Cosmos DB account. The business accepts slightly stale stock data but sets a hard limit on how stale.",
