            B.q("ai-m3-28", "ai-pgvector", "An IVFFlat index is being built on 500,000 existing rows. Which starting settings does Microsoft suggest?", listOf("lists = sqrt(rows) (about 707) at build time, and probes starting at sqrt(lists) (about 27)", "lists = rows / 1000 (500) at build time, and probes starting at lists / 10 (50) at query time", "lists = rows (500,000), one list per row, and probes = 1 so each search reads one list", "lists = rows / 1000 (500) at build time, and probes equal to lists (500) at query time"), setOf(1), "IVFFlat clusters vectors into lists. For up to a million rows, start with lists = rows / 1000 and probes = lists / 10; more probes searches more lists, raising recall and cost. If probes equals lists, the search is effectively exact.",
                scenario = "Fernway Health indexes 500,000 symptom-note embeddings in Azure Database for PostgreSQL.",
                whyWrong = mapOf(
